import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"RTK Corrections","description":"","frontmatter":{},"headers":[],"relativePath":"en/qgc-user-guide/settings_view/ntrip_rtk.md","filePath":"en/qgc-user-guide/settings_view/ntrip_rtk.md"}`),a={name:`en/qgc-user-guide/settings_view/ntrip_rtk.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="rtk-corrections" tabindex="-1">RTK Corrections <a class="header-anchor" href="#rtk-corrections" aria-label="Permalink to “RTK Corrections”">​</a></h1><p>Configure where RTK corrections come from and how they reach vehicles: the built-in NTRIP client, a local base station, or RTCM received over UDP.</p><h2 id="corrections-status" tabindex="-1">Corrections Status <a class="header-anchor" href="#corrections-status" aria-label="Permalink to “Corrections Status”">​</a></h2><p>Shows the correction stream currently sent to vehicles and its data rate. The toolbar GNSS indicator also offers <strong>Connect</strong> once an NTRIP server is configured.</p><h2 id="ntrip-connection" tabindex="-1">NTRIP Connection <a class="header-anchor" href="#ntrip-connection" aria-label="Permalink to “NTRIP Connection”">​</a></h2><p>Shows the NTRIP connection state with message and byte counters, the age of the last correction, and a Connect/Disconnect button.</p><h2 id="ntrip-server" tabindex="-1">NTRIP Server <a class="header-anchor" href="#ntrip-server" aria-label="Permalink to “NTRIP Server”">​</a></h2><ul><li><strong>Host address</strong> — NTRIP caster hostname or IP</li><li><strong>Server port</strong> — NTRIP caster port (default: 2101)</li><li><strong>Username</strong> — NTRIP account username</li><li><strong>Password</strong> — NTRIP account password (with show/hide toggle)</li><li><strong>Use TLS encryption</strong> — connect with TLS 1.2 or later</li><li><strong>Accept self-signed TLS certificates</strong> — accept a caster whose certificate is self-signed. The first successful connection records that certificate; a later connection that presents a different one fails, reporting that the caster&#39;s certificate changed. Turning the option off forgets the recorded certificate. Certificates signed by a trusted authority are never recorded.</li></ul><h2 id="ntrip-mountpoint" tabindex="-1">NTRIP Mountpoint <a class="header-anchor" href="#ntrip-mountpoint" aria-label="Permalink to “NTRIP Mountpoint”">​</a></h2><ul><li><strong>Mount Point</strong> — the NTRIP mountpoint to connect to</li><li><strong>Browse</strong> — fetch available mountpoints from the server and display them in a list with format, navigation system, country, bitrate, and distance information</li></ul><h2 id="gga-position-reporting" tabindex="-1">GGA Position Reporting <a class="header-anchor" href="#gga-position-reporting" aria-label="Permalink to “GGA Position Reporting”">​</a></h2><p>Network RTK (VRS) casters need the rover position. Select the position QGC reports and how often.</p><h2 id="ntrip-message-filter" tabindex="-1">NTRIP Message Filter <a class="header-anchor" href="#ntrip-message-filter" aria-label="Permalink to “NTRIP Message Filter”">​</a></h2><ul><li><strong>RTCM Message Filter</strong> — whitelist of RTCM message types to forward from NTRIP (empty = forward all)</li></ul><h2 id="udp-rtcm-input" tabindex="-1">UDP RTCM Input <a class="header-anchor" href="#udp-rtcm-input" aria-label="Permalink to “UDP RTCM Input”">​</a></h2><ul><li><strong>Enable UDP RTCM input</strong> — receive RTCM corrections over UDP, for example from another application. UDP input is used alongside NTRIP and a local base station, and incoming data is always checked to be valid RTCM.</li><li><strong>UDP RTCM input port</strong> — port to listen on (default: 13320, range: 1024–65535)</li></ul><h2 id="udp-forwarding" tabindex="-1">UDP Forwarding <a class="header-anchor" href="#udp-forwarding" aria-label="Permalink to “UDP Forwarding”">​</a></h2><ul><li><strong>Forward corrections over UDP</strong> — forward the stream selected for vehicles to another device or application</li><li><strong>UDP output address</strong> — destination IP for forwarded data</li><li><strong>UDP output port</strong> — destination port for forwarded data</li></ul><h2 id="correction-routing" tabindex="-1">Correction Routing <a class="header-anchor" href="#correction-routing" aria-label="Permalink to “Correction Routing”">​</a></h2><ul><li><strong>Vehicle correction source</strong> — <em>Highest priority</em> sends one fresh stream to vehicles, preferring the local base station, then NTRIP, then UDP, and switches when the preferred stream stops. Selecting a source category uses only that category, without falling back to another. When several UDP senders deliver, QGC stays on the first fresh one.</li></ul><p>Vehicles and UDP forwarding always receive the same stream.</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};